<template>
  <view class="page">
    <view v-if="module.key" class="head"><view class="head-row"><text class="scene-icon">{{module.icon}}</text><view class="head-copy"><text class="world">{{module.world}} · {{module.stage}}</text><text class="title">{{module.title}}</text><text class="sub">{{module.subtitle}}</text></view><text class="count">{{module.passedLevels}}/{{module.totalLevels}}</text></view><view class="bar"><view :style="{width:percent+'%'}"></view></view></view>
    <scroll-view class="level-scroll" scroll-y :scroll-top="scrollTop" scroll-with-animation>
      <animated-loading v-if="loading" text="正在加载场景..."></animated-loading>
      <view v-else class="path"><view v-for="(item,i) in levels" :id="'module-level-'+i" :key="item.key" class="step" :class="[position(i),item.status,starClass(item),{boss:item.isBoss}]" :style="{animationDelay:(i%12)*45+'ms'}" @click="open(item)"><view v-if="i<levels.length-1" class="connector" :class="[line(i), { 'conn-locked': !levels[i+1].unlocked }]"></view><view v-if="item.unlocked&&item.status!=='passed'" class="pulse"></view><view class="node"><text>{{icon(item)}}</text></view><text class="step-title">{{item.title}}</text><text class="step-sub">{{shortLabel(item.subtitle)}}</text><text v-if="item.status==='passed'" class="stars">{{'★'.repeat(item.stars)}}{{'☆'.repeat(3-item.stars)}}</text></view><view class="finish">🏆<text>完成场景挑战后解锁下一场景</text></view></view>
    </scroll-view>
  </view>
</template>
<script>import{request}from'@/utils/api.js';import{isFirstLoad}from'@/utils/first-load.js';export default{data(){const firstLoad=isFirstLoad('pages/adventure/module');return{key:'',firstLoad,loading:firstLoad,module:{},levels:[],scrollTop:0}},computed:{percent(){return this.module.totalLevels?Math.round((this.module.passedLevels||0)*100/this.module.totalLevels):0}},onLoad(q){this.key=String(q.key||'')},onShow(){this.load()},methods:{focusCurrentLevel(){if(!this.levels.length)return;let i=this.levels.findIndex(x=>x.unlocked&&x.status!=='passed');if(i<0)i=Math.max(0,this.levels.length-1);setTimeout(()=>{const q=uni.createSelectorQuery().in(this);q.select('.level-scroll').boundingClientRect();q.select('.path').boundingClientRect();q.select('#module-level-'+i).boundingClientRect();q.exec(r=>{const viewport=r?.[0],path=r?.[1],level=r?.[2];if(!viewport||!path||!level)return;const target=Math.max(0,level.top-path.top-viewport.height*.18);this.scrollTop=-1;this.$nextTick(()=>{this.scrollTop=target})})},80)},async load(){if(this.firstLoad){this.loading=true;this.firstLoad=false}try{const d=await request('/adventure-course/module/'+this.key+'/levels');this.module=d.module;this.levels=d.levels||[]}catch(e){uni.showToast({title:e.message||'加载失败',icon:'none'})}finally{this.loading=false;this.$nextTick(()=>this.focusCurrentLevel())}},starClass(x){return x.status==='passed'?'stars-'+Math.max(1,Math.min(3,Number(x.stars||1))):''},position(i){return['center','right','center','left'][i%4]},line(i){return['to-right','to-left','to-left','to-right'][i%4]},icon(x){if(x.status==='passed')return'★';if(x.status==='locked')return'🔒';if(x.isBoss)return'🏆';if(x.subtitle.includes('音标'))return'🔊';if(x.subtitle.includes('词汇'))return'📚';if(x.subtitle.includes('语法'))return'✍️';if(x.subtitle.includes('听力'))return'🎧';return'▶'},shortLabel(v){return String(v||'').split('·')[0]},open(x){if(!x.unlocked)return uni.showToast({title:'请先完成上一关',icon:'none'});uni.navigateTo({url:'/pages/adventure/practice?id='+x.key})}}}</script>
<style>.page{box-sizing:border-box;height:100vh;display:flex;flex-direction:column;overflow:hidden;padding:22rpx 22rpx 0;background:linear-gradient(180deg,#edf5f6,#f7f5f0)}.head{flex-shrink:0;padding:25rpx;border-radius:26rpx;background:linear-gradient(130deg,#1f3a5f,#256d78);color:#fff;box-shadow:0 12rpx 28rpx rgba(31,58,95,.2)}.head-row{display:flex;align-items:center}.scene-icon{font-size:45rpx;margin-right:16rpx}.head-copy{flex:1}.world{display:block;font-size:19rpx;color:#8ee0d4;font-weight:800}.title{display:block;margin-top:3rpx;font-size:32rpx;font-weight:900}.sub{display:block;margin-top:4rpx;font-size:19rpx;color:#bed0da}.count{font-size:22rpx;font-weight:900}.bar{height:8rpx;margin-top:18rpx;border-radius:8rpx;background:rgba(255,255,255,.18);overflow:hidden}.bar view{height:100%;background:#70d1c5}.level-scroll{flex:1;height:0;min-height:0;margin-top:18rpx}.path{position:relative;margin-bottom:40rpx;padding:35rpx 0 60rpx;border-radius:28rpx;background:linear-gradient(#e3f3ef,#eef3df);overflow:hidden}.step{position:relative;opacity:0;animation:levelEnter .48s cubic-bezier(.2,.8,.25,1) forwards;height:150rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:2}.step.center{margin-left:50%;transform:translateX(-50%);width:190rpx}.step.left{margin-left:10%;width:190rpx}.step.right{margin-left:calc(90% - 190rpx);width:190rpx}.node{z-index:2;display:flex;align-items:center;justify-content:center;width:78rpx;height:78rpx;border:10rpx solid rgba(255,255,255,.8);border-radius:50%;background:#1f3a5f;color:#fff;box-shadow:0 9rpx 0 #142b47;font-size:29rpx}.locked .node{background:#9aabad;box-shadow:0 9rpx 0 #758789}.passed.stars-1 .node{background:linear-gradient(135deg,#10B981,#34D399);box-shadow:0 9rpx 0 #087f5b}.passed.stars-2 .node{background:linear-gradient(135deg,#3B82F6,#60A5FA);box-shadow:0 9rpx 0 #2563b8}.passed.stars-3 .node{background:linear-gradient(135deg,#7C3AED,#A855F7);box-shadow:0 9rpx 0 #5b21b6}.passed .node{animation:passedFloat 2.8s ease-in-out infinite}.boss .node{width:92rpx;height:92rpx;background:#d97835}.step-title{position:relative;z-index:1;margin-top:12rpx;padding:3rpx 10rpx;border-radius:12rpx;background:#fff;font-size:24rpx;line-height:1.25;font-weight:900;color:#36566a}.step-sub{position:relative;z-index:1;margin-top:6rpx;padding:2rpx 10rpx;border-radius:10rpx;background:#fff;font-size:20rpx;line-height:1.25;color:#71858c}.stars{margin-top:5rpx;font-size:25rpx;line-height:1;letter-spacing:3rpx}.stars-1 .stars{background:linear-gradient(90deg,#10B981,#34D399);-webkit-background-clip:text;color:transparent}.stars-2 .stars{background:linear-gradient(90deg,#3B82F6,#60A5FA);-webkit-background-clip:text;color:transparent}.stars-3 .stars{background:linear-gradient(90deg,#7C3AED,#A855F7);-webkit-background-clip:text;color:transparent;text-shadow:0 2rpx 8rpx rgba(124,58,237,.22)}.connector{position:absolute;z-index:0;top:75rpx;left:50%;width:44rpx;height:190rpx;margin-left:-22rpx;transform-origin:top;background-repeat:no-repeat;background-size:100% 100%}.connector.conn-locked{opacity:.35}.to-right{transform:rotate(-47deg);background-image:url("data:image/png;base64,")}.to-left{transform:rotate(47deg);background-image:url("data:image/png;base64,")}.pulse{position:absolute;top:20rpx;width:105rpx;height:105rpx;border:4rpx solid rgba(13,148,136,.35);border-radius:50%;animation:pulse 1.7s infinite}.finish{display:flex;flex-direction:column;align-items:center;margin-top:20rpx;font-size:48rpx}.finish text{margin-top:9rpx;font-size:20rpx;color:#7e8e87}.state{text-align:center;padding:130rpx;color:#84919c}@keyframes levelEnter{0%{opacity:0;top:16rpx}100%{opacity:1;top:0}}@keyframes passedFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4rpx)}}@keyframes pulse{0%{transform:scale(.8);opacity:1}100%{transform:scale(1.25);opacity:0}}</style>




